SELECT DISTINCT tb.expp_lvl_nm
  FROM tmm_bztgtprdcexppinfom tb
 WHERE ${queryWhere}
   AND tb.prdc_fulf_dt = #{predictDate}
   AND tb.del_yn = 'N'
 ORDER BY tb.expp_lvl_nm

SELECT mrkt_idx_anly_tgt_cd , prdc_fulf_dt , mnmnc_cd , prdc_rslt_dt , expp_titl_cntt , expp_smry_cntt , expp_cntt_file_path_nm FROM tmm_bztgtprdcexppcnttm WHERE ${queryWhere} AND prdc_fulf_dt = #{date} AND del_yn = 'N'
AND prdc_rslt_dt BETWEEN #{startDate} AND #{endDate}
ORDER BY prdc_fulf_dt DESC, prdc_rslt_dt DESC
